INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter21-telangana-newspapers-literature', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter21-telangana-newspapers-literature-p1", "partName": "Newspapers and the Press in Telangana", "bodyMd": "India''s first newspaper was the **Bengal Gazette**, started by **James Augustus Hicky in 1780**. In the Hyderabad State, the Nizam Government''s ordinance **Gasti Nishan 53** banned freedom of expression and the press. English, Telugu, and Urdu newspapers were published across the state precisely to create awareness among the people while working around this restriction.\n\nDiverse linguistic communities — Telugu, Marathi, Urdu, and Kannada speakers — lived together in the erstwhile Hyderabad State, though Telugu speakers formed the majority and Urdu held official-language status. In such conditions, learned Telugu individuals took up book publication, library founding, socio-cultural reform movements, and newspaper launches to awaken the public.\n\n### Printing Presses\n\n*   **Brahma Vidya Vilasam Printing Press (1870)** — established by the **Wanaparthy rulers**; the first printing press in the Hyderabad State.\n*   In **1875**, a printing press was established at **Gadwal Samsthanam**.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter21-telangana-newspapers-literature-p2", "partName": "Early Newspapers of Hyderabad State (Urdu, Persian, English)", "bodyMd": "| Newspaper | Year | Notes |\n|---|---|---|\n| Jubdoot-Ul-Akbar | 1833 | One of the earliest newspapers of India; established at Hyderabad. |\n| Risala Tabbi | 1859 | A medical journal in Urdu; the first newspaper published in Hyderabad. |\n| Octareshfak | 1878 | Published in Parsi language; some scholars consider it the first newspaper in the Nizam State. |\n| Deccan Times | 1864 | First English newspaper from Hyderabad; established by Abdul Khader. |\n| Hyderabad Recorder | 1885 | English newspaper; the first newspaper banned by the Nizam Government (1892), after it described the British Resident as \"Kaizer\" and Britain pressured the Nizam to act. |\n| Hyderabad Bulletin | 1904 | English-language paper started by Cameroon; despite Nizam-era restrictions, it boldly published news against the government and survived for nearly 50 years. |\n\n**Maulim-e-Niswan (1892)** was started by **Maulvi Mohib Hussain** to propagate reforms for Muslim women; he is known as the father of journalism in Hyderabad and carried the titles \"Hyderabad Women''s Education Vaithalika\" and \"Telangana Sir Syed Ahmed Khan.\"", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter21-telangana-newspapers-literature-p3", "partName": "Telugu Newspapers of Telangana", "bodyMd": "| Newspaper | Year | Founder/Editor | Notes |\n|---|---|---|---|\n| Shedya Chandrika | 1886 | Munshi Mohammed Musthak Ahmed Malik | Considered by recent researchers, including **Sangishetty Srinivas**, to be the first Telugu newspaper published in Telangana. It was a translation of the Urdu magazine _Punoon_ and provided agricultural information. |\n| Deenvarthaman | 1890–91 | Narayana Swamy Mudaliar (Sultan Bazar, Hyderabad) | Per researchers **Rapolu Andhra Bhaskar** and **Veludurthi Manikya Rao**, the first daily Telugu newspaper. Narayana Swamy had earlier run the weekly _Asaf-Ul-Akbar_ from 1878. |\n| Hithabodhini | 1913 | Bandaru Srinivasa Sharma | A weekly magazine published from Mahabubnagar; the first Telugu newspaper distributed all over Telangana. Sharma was a Sanskrit scholar and Ayurvedic doctor from Koyala Konda, Mahabub Nagar. The **Atmakuru ruler Sri Rama Bhupala Bahiri Balawant Bahadur** financed the printing machine for this paper. |\n| Nilgiri | 1922 | Shabnaveesu Venkatarama Narsimha Rao | The first political weekly magazine in Telangana. The editor also founded a library named \"Samskarini\" and wrote the poem _Balika Vilapam_. |\n| Tenugu Vara Patrika | 27 August 1922 | Oddiraju Sitaramachandra Rao and Oddiraju Raghava Ranga Rao | The Oddiraju brothers printed this paper at their own Inugurthi printing press in Inugurthi village (Mahabubabad district); they had also founded **Vignana Pracharini Sri Grandhamala (1919)** for educational books. |\n| Golconda Patrika | 10 May 1926 | Suravaram Pratap Reddy (editor); centred at Nalgonda | Published Political, Economic, Social, and Cultural news of Telangana as a half-weekly (Wednesday and Saturday). Suravaram first wanted to name it _Andhra Patrika_, but the Nizam Government opposed this, so he chose the name \"Golconda\" instead. In **1947** it became a daily; it was closed in **1966**. |\n| Sujatha Patrika | 1927 | Pasumamula Narsimaha Sharma (editor) | Literary monthly magazine from Hyderabad; its name was suggested by **Rayaprolu Subba Rao**. |\n| Bhagyanagar Patrika | 1931 | Bhagya Reddy Varma | Founded for the development of Dalits; its front page carried images of Charminar, Mecca Masjid, and Ellora–Ajanta paintings. From 1937 it was renamed **Adi Hindu Newspaper**. |\n| Phula Thota Patrika | 1930–35 | Kambampati Appanna Shastri (editor); Hanumakonda | The first children''s paper in Telangana. |\n| Telugu Talli | 1939 | Rachamalla Satyavati Devi (editor) | A monthly magazine; the first paper published by a woman editor in Telangana. |\n| Telangana Patrika | 1942 | Rajgopal Mudaliyar (founder); Bukkapatnam Ramanuja Chary (editor) | The first daily newspaper from Telangana. |\n| Kakatiya Vaara Patrika | 1946 | P.V. Narasimha Rao (founder); Pamulaparthi Sadashiva Rao (editor) | — |\n| Shoba | 1947 | Devulapalli Ramanuja Rao | A literary monthly magazine. Devulapalli also ran a secret newspaper from Kurnool titled \"State Congress Vartha Sanchika\" in 1947. |\n\n### Nilgiri–Tenugu Patrika Rivalry\n\nThe **Nilgiri Patrika**, founded in **1922** by editor **Shabnaveesu Venkatarama Narasimha Rao**, was published from **Nalgonda** as the first fully-fledged political weekly in Telangana. Just three days after Nilgiri began, on **27 August 1922**, the **Oddiraju brothers** launched **Tenugu Patrika** from **Inugurthi** in the Manukota taluka.\n\nBecause Nilgiri was centred in Nalgonda rather than at the district''s administrative headquarters, Tenugu Patrika enjoyed some regional advantage, being published from a village that was itself gaining prominence. However, this created printing difficulties for Tenugu Patrika: since the press was village-based, it struggled to find people who could work the printing machinery — local youths had to be trained specifically for the task — and readers had to arrange postage from Mahabubabad to receive their copies.\n\nThere being no radio or television at the time, newspapers were the sole channel through which people learned of national events, and news itself did not travel quickly. Because of this, newspapers depended on the nearest railway station to receive dispatches — someone even had to fetch coastal/overseas news via a personal contact.\n\nSince editorial responsibility for Tenugu Patrika rested solely with the Oddiraju brothers, both had to write content themselves regardless of who was available, and with a limited subscriber base, running the paper for **five years** from such a small village was regarded as a remarkably bold achievement. Alongside publishing the paper, the Oddiraju brothers also ran a book series called **Vignana Pracharini Grandhamala**.\n\n**Nilgiri Patrika** was edited with great competence by **Shabnaveesu Ramanarasimha Rao** until **1925**. Prominent contemporary leaders — **Madapati Hanumantha Rao**, **Bandaru Ramakrishna Rao**, and **Pulijala Rangarao**, among others — contributed poems and essays on various subjects to this paper.\n\nAround this time, Nilgiri refused to publish a sensational story written by **Gudipati Venkatachalam**; Shabnaveesu''s decision to reject it itself created a stir. The pioneer of the Andhra movement, **Ramanarasimha Rao**, died in **1929**.\n\n### Suravaram Pratap Reddy and Golconda Patrika\n\n**Suravaram Pratap Reddy** awakened the Telangana public continuously through the **Golconda Patrika** from **1926 to 1946**. It was initially a bi-weekly with outstanding editorials that were a thorn in the side of the Nizam government; it became a daily in **1947**, with Prataparao (Pratap Reddy) as editor throughout, an editorship he never relinquished.\n\nUntil Golconda Patrika emerged, the library movement, the Andhra movement, and papers such as Nilgiri and Tenugu Patrika had been mutually dependent for survival. In **1923**, **Mudigonda Veerabhadra Sastry** started a monthly magazine titled _Shaiva Pracharini_ from Warangal; in that period, Tenugu Patrika and Shaiva Pracharini were engaged in a spirited (healthy) rivalry.\n\n### Sujatha, Andhrakesari, Deshabandhu and Related Papers\n\n**Sujatha**, edited by **P.N. Sarma**, concluded with its fourth issue''s first number in **1927**. In **1924**, **Adusumilli Dattatreya Sarma** started a weekly paper, _Andhrakesari_, in the Andhra-Telugu language from Secunderabad; it ran for **five years**. The monthly _Deshabandhu_, from Vaddepalli village of Atraf-e-Balda district, was run for three years by **Bellamkonda Ramanujacharyulu** and his brother **Narasimhacharyulu** together.\n\n**B.N. Sarma**, a resident of Ramannapet taluka, Nalgonda district, was proficient in Telugu, Sanskrit, and English. He trained in journalism under Nilgiri Patrika editors **Shabnaveesu Venkatarama Narasimha Rao** and **Madapati Hanumantha Rao**.\n\nWhen the Nizam government harassed him with a battery of legal questions over his paper''s printing decisions, he could not bear it, moved to Bezwada, and ran a paper called _Andhravani_ there for five years; it achieved wide circulation, and the street where its office stood is still called \"Andhravani Street.\" Sarma, who worked at many papers, died in **1970**.\n\n### Ramanujacharyulu and the \"Telangana\" Daily\n\nIn **1929**, **Bukkapatnam Ramanujacharyulu** started the **Hyderabad Bulletin** paper in Hyderabad city. He was the pioneer who first introduced English and Telugu newspaper publication in Telangana.\n\nIn **1942**, the **Telangana** daily was published under his editorship; it featured a daily \"Charminar Gossip\" column. It disclosed the secrets of Nawabi-era administrative offices and high officialdom, which readers eagerly consumed the next day. He was skilled in both English and Telugu writing.\n\nHe later joined his friend and colleague **Rajagopal** to start the **Deccan Chronicle** weekly in **1937**, of which he was the editor; it became a daily in **1939**. After his ties with Deccan Chronicle ended, he started an evening paper called **Garrison**.\n\nIn **1947** he started the English daily **Daily News**, but died within a month of its launch.\n\n### Bhagyanagar Patrika and Adi Hindu Patrika\n\nIn **1925**, the prominent social-reform figure **Bhagya Reddy** established the **Bhagyanagar Patrika**. When Bhagya Reddy fell ill and had to leave for Mysore, the paper was discontinued.\n\nAfter recovering and returning from Mysore, he restarted it, in the cause of Harijan upliftment, as the weekly **Adi Hindu Patrika**. This paper discussed many political issues and championed the political movements of the Nizam-era public.\n\n### Other Papers of the 1920s–1940s\n\nThe **Vibhuti** paper was run under the editorship of **Veerabhadra Sharma**. The **Shobha** paper, run from Warangal under the editorship of **Devulapalli Ramanujarao**, was a prominent literary paper but had to close within a single year due to financial constraints.\n\nBetween **1938 and 1945**, few new papers emerged, owing to the Nizam government''s severe restrictions on freedom of speech. In **1945**, **Challa Subbarao** started a Telugu monthly called **Tarani**. The prominent Urdu paper _Payam_''s editor **Khwaja Abdul Gaffar** started a Telugu paper, **Sandesham**; it ran for only six months.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter21-telangana-newspapers-literature-p4", "partName": "Urdu Newspapers", "bodyMd": "| Newspaper | Year | Founder/Editor | Notes |\n|---|---|---|---|\n| Payam | 1935 | Khaji Abdul Gaffar | An Urdu daily that supported the independence struggle of the Nizam''s subjects. |\n| Rayyat | 1927 | Mandamula Narsingh Rao | An Urdu weekly (\"Rayyat\" means a farmer); it informed national leaders of the anti-Nizam movement in Hyderabad, demanded a responsible government in the Nizam State, and fought for people''s rights. **Shoebullah Khan**, later editor of _Imroze_, initially worked here. |\n| Imroze | 1947 | Shoebullah Khan | An Urdu weekly (\"Imroze\" means fire). Shoebullah began his career at the Urdu weekly _Tej_, then worked at _Rayyat_ before starting Imroze, through which he criticised the Razakars and wrote editorials advocating Hyderabad''s merger into the Indian Union. As a result, he was murdered by the Razakars on **20 August 1948**. |\n| Rahbar-e-Deccan | — | Ahmed Mohinuddin and Abdullahkhan (editors) | Supported by the MIM party. |\n| Meezan | 1944 | Gulam Mohammed (Gulam Alauddin) of Calcutta | The word \"Meezan\" is Arabic for \"the balance.\" It was the first paper in Telangana published in three languages — Telugu, English, and Urdu — and the first daily newspaper to run serialised novels. |\n\n### Meezan''s Structure\n\nMeezan''s Urdu edition supported the Razakars, its English edition supported the Nizam, and its Telugu edition supported communists and other radicals. The Telugu edition''s editor was **Adavi Bapiraju**, with **Vidwan Viswam** as sub-editor.\n\nAdavi Bapiraju published stories and songs by **Avula Pichaiah** of Suryapet, and his own serialised novels — _Himabindu_, _Gona Gannareddy_, and _Toofan_ — appeared in Meezan. Contributors to the paper included **Tirumala Ramachandra**, **Rachakonda Krishnamurthy**, **Srinivasa Chakravarti**, and **Bommakanti Subbarao**. Bapiraju''s own columns \"Dhoopadeepalu\" and \"Mirchi Masala\" entertained and informed readers.\n\nMeezan ran for three years; as Razakar atrocities intensified across the state, Bapiraju resigned his editorial duties on **7 August 1947**.\n\n**Vatan News (Momibbe Vatan)** was founded by **Mustafa Qadri**: at a time when the pro-Nizam news agency **Deccan News** was disseminating pro-government propaganda, Qadri — a critic of Muslim fundamentalism — started the news agency **Vatan News** and its paper _Momibbe Vatan_ (\"patriot\") to publish unbiased news. **Ganapati Rao Akhilekar**, through his agency **Modern News**, similarly circulated the pro-government news supplied by Deccan News agency''s _Deccan News_.\n\n**Masawat** (meaning \"Equality\") was an Urdu weekly started by **Prem Kumar**, Vice-President of the Hyderabad Depressed Classes Federation.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter21-telangana-newspapers-literature-p5", "partName": "Other Notable Papers and Editors", "bodyMd": "| Paper | Year | Editor/Founder |\n|---|---|---|\n| Andhra Matha Paper | 1917 | Swamy Venka' WHERE chapter_slug = 'telangana-history-en-chapter21-telangana-newspapers-literature';
UPDATE theory_content SET concepts_json = concepts_json || 't Rao; published on behalf of the Divine Life Society, Secunderabad |\n| The Panchama | 1918–20 | J.S. Mathaiah |\n| Desivajmaya | 1921 | Telangana Literacy Association |\n| Shaivamata Pracharini | 1923 | Mudigonda Veeresha Linga Shastri |\n| Shaivamani | 1924 | Mudigonda Buchaiah |\n| Ahakam Sube Warangal | 1925 | Run by Revenue officers from Warangal; considered the first fortnightly paper in Telangana |\n| Nedu Patrika | 1925 | Bhaskar (Secunderabad) |\n| Andhra Abhyudayam | 1925 | Kokila Sitarama Sharma |\n| Deshabandhu | 1926 | Bellamkonda Narasimha Charyulu; tagline \"Andhra Vignana Prabodha\" monthly magazine |\n| Kashtukar | 1931 | Mohammad Abdul Razaq Bismil; a bilingual Urdu–Telugu peasant journal published from Dablipura, Hyderabad |\n| Vaidyakala | 1931 | M. Anantharanga Charyulu |\n| Deccan Kesari | 1934 | Adusumalli Venkat Dattatreya Sharma |\n| Divyavani | 1937 | Chivukula Appaiah Sastry |\n| Andhravani | 1938 | Bonguluri Narasimha Sharma; published from Vijayawada owing to unfavourable conditions in Hyderabad during the State Congress Satyagraha |\n| Vibuthi | 1939 | Chidiremattam Veerabhadra Sharma |\n| Sandesham | 1941 | Quazi Abdul Gaffar |\n| Andhra Kesari | 1941 | Gundavaram Hanumanth Rao |\n| Samstana Vidyartri | 1945 | Bheema Goud |\n| Telugu Desam | 1948 | Suryadevara Rajya Lakshmi |\n| Sudarshan Patrika | — | Sudarshana Devi; monthly, published from Wanaparthy |\n| Janashakti | 1950–54 | Juvvadi Goutam Raju, Raghuveerarao |\n| Prajavani | 1951 | Suravaram Pratap Reddy |\n| Navayuga | 1954 | Telangana Writers Association |\n| Padma Prakash | — | Burgula Ramakrishnaiah (monthly magazine) |\n| Hyderabad Weekly | — | Maari Chenna Reddy |\n\n### Telugu Book Distribution under the Nizam\n\nDuring the Nizam period, besides the **Srikrishna Devaraya Andhra Basha Nilayam** in Hyderabad, there was only one Telugu book stall in the entire Nizam State, run by **Nampalli Gouri Shankar Sharma**. He distributed Telugu books across the state and, for this service, was regarded as a \"language servant.\"", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter21-telangana-newspapers-literature-p6", "partName": "Pioneers of Research and Literature in Telangana", "bodyMd": "### Komarraju Venkat Laxman Rao (1876–1923)\n\n*   The first person to conduct research into Telangana''s literature.\n*   Born in **Penuganchiprolu** (Krishna district); later settled in **Bhuvanagiri**, Telangana.\n*   Worked as Diwan to the Munagala Zamindar, **Raja Nayani Venkat Ranga Rao**.\n*   Established several libraries and authored many books; proved that the ancient city of **Ekasila** was not Ontimetta in Kadapa district but was, in fact, **Orugallu** (Warangal).\n*   **Books:** Shivaji Chritra, Haindava Chakravarthulu, Hindu Mahayugam, Mohammadain Mahayugam, and Andhra Vignana Sarvasvam (the first Vignana Sarvasvam/encyclopaedia in Telugu).\n*   In **1910**, he wrote Telangana''s first short story, _Ebadivella Bheramu_, though some scholars instead credit **Madapati Hanumanthrao''s** 1912 story _Hrudaya Shalyamu_ as the first.\n\n### Manavalli Ramakrishna Kavi (1866–1957)\n\n*   Served as personal secretary to the Wanaparthy ruler **Sawai Rameshwar Rao Bahadur**.\n*   Collected inscriptions and published them as _Lithic Records of Hyderabad State_.\n*   Published ancient texts in a series titled _Visrutha Kavulu_.\n\n### Seshadri Ramana Kavulu\n\n*   Established the **Historical Research Council** (Charitraka Parishodaka Mandali) at Hanumakonda.\n*   In **1931**, organized the **Akhilandhra Historical Conference**.\n*   Key literary work: _Andhra Veerulu_.\n\n### Adiraju Veerabhadra Rao\n\n*   Born in **Dendukur** (Madhira Taluka, Khammam district); given shelter in Hyderabad by **Ravi Chettu Ranga Rao**.\n*   Established the **Andhra Research Council** (Andhra Parishodaka Mandali) under the Andhra Jana Kendra Sangam.\n*   The first person to give a speech on Hyderabad Radio.\n*   Collected Telangana''s inscriptions and published two volumes as _Telangana Inscriptions_.\n*   **Other writings:** Mana Telanganamu, Ratnaprabha, Chaitanyamu, Jeevita Charitavali, Lalitha Kalavali, Navvula Puvvulu, and _Ancient Cities of Andhra_ — covering the history of twelve ancient cities including Kondapur, Kolanupaka, Anegondi, Alampur, Bhuvangiri, Rachakonda, Warangal, and Pangal.\n\n### Suravaram Pratap Reddy (1896–1953)\n\n*   Born in **Itikyalapadu** village, Jogulamba Gadwal district.\n*   Because contemporary Andhra poets claimed Telangana had no poets, he was moved to research Telangana''s literature.\n*   In **1934**, compiled **Golconda Kavulu**, a list of the works of **354 Telangana poets**, to prove that Telangana possessed a rich literary and poetic tradition.\n*   Wrote _Andhrulu Saanghika Charitra_, a social history of the Telugu people, which won the **Kendra Sahitya Academy Puraskaram in 1955** — making him the **first Telugu poet** to receive the award.\n*   Autobiography: _Svavishaya Sangraham_.\n*   Started and edited the **Golconda Patrika** in 1926; founded the **Vigyana Vardhini Parishad** in 1941; ran **Prajavani Patrika** in 1951–52.\n*   Wrote under several pen names, including Chitra Gupta, Jagam Basavaiah, Vishwamitra, Yugapati, Amrutha Kalasi, Sangrama Simha, Bhava Kabi Ram Murthy, and Bahadur.\n*   **Stories:** Mogalayi Kathalu; **comic/satirical writings:** Verrivengalappa, Kavilekattalu.\n*   **Research works:** Golconda Kavula Sanchika (1934), Hinduvula Pandugalu (1931), Ramayana Visheshalu (1943), Prapancha Grandalaya Charitra, Lipi Samskaranalu.\n*   **Dramas:** Uchchala Vishadamu (based on Kalhana''s Rajatarangini), Baktha Tukaram.\n*   **Novels:** Arevirulu, Suddantha Katha.\n*   **Poetry & Prose:** Sangala Panthulu, Hamsaveera Sambhavam, Padmini, Mohammed Ghazni, Deshanata.\n*   In the **first general elections of Hyderabad State (1952)**, he was elected to the legislative assembly (Congress Party) from the Wanaparthy constituency.\n\n### Biruduraju Ramaraju\n\n*   Native of **Devanuru** village, Warangal district.\n*   Researched folklore literature; awarded a Ph.D. in Telugu literature by **Osmania University in 1956**.\n*   **Literary works:** Maruguna Padina Manikyalu, Charitra Kekkina Charitardulu, Andhra Yogulu.\n*   Discovered and researched: Kakatiya Prataparudra''s _Usha Ragodhayam_, Sri Krishna Devaraya''s _Jambavati Parinayam_, Palkuriki Somanatha''s _Panditharadhya Charitra_ and _Basavodaharanam_, Srinatha''s _Shiva Ratri Mahatyam_, and Madiki Singanna''s _Padma Puranam_.\n\n### Daasarathi Krishnamacharyulu (1925–1987)\n\n*   Born in **Chinnaguduru** village, Warangal district (now in Mahabubabad district).\n*   Held a B.A. in English literature from Osmania University; worked as a teacher and Akashavani speaker.\n*   Served as **Court Poet of Andhra Pradesh, 1977–83**; titles: Kalaprapurna and Abhyudhaya Bhaavi.\n*   Won the **Kendra Sahitya Academy Award in 1974** for _Timiramto Samaram_ (\"Fight against Darkness\").\n*   As part of the **Andhra Mahasabha**, travelled village to village to raise public awareness; arrested by the Nizam government in **1947** and imprisoned at **Induru Fort Jail, Nizamabad** for his role in the public agitation — along with poet **Vattikota Alwar Swamy**. He used to write poems on the jail walls with charcoal (meant for brushing teeth); police mistakenly attributed and punished Vattikota for these.\n*   Founded **Telangana Rachayithala Sangam** (Telangana Writers'' Association) in **1953** and served as its president.\n*   Entered cinema in **1961**, writing lyrics for _Iddaru Mitrulu_.\n*   **Literary works:** Agnidhara (on the Telangana Armed Struggle), Rudraveena, Navami, Punarnavam, Mahashilpi Jakkanna, Mahandrodyamam, Kavitha Pushpakam, Timiramto Samaram, Amruthabishekam, Mahaboddhi, Ghalib Geethalu, Alochanalochanalu. He received the **Andhra Pradesh Sahitya Academy Award** for _Kavitha Pushpakam_.\n*   The **1st Daasarathi Krishnamacharya Award** was given by the Telangana Government to **Tirumala Srinivasa Charyulu** (Karimnagar).\n\n### Daasarathi Rangacharya (1928–2015)\n\n*   Born in **Chinnaguduru** village, Warangal district; brother of Daasarathi Krishnamacharya.\n*   Expelled from school in the 6th standard for organising a strike (wearing Gandhiji''s cap instead of the Nizam-prescribed uniform); worked as a teacher from **1951–57**.\n*   Known as **Akshara Vachaspathi** and **Telangana Karadeepika**; participated in the Telangana Armed Struggle.\n*   Autobiography: _Jeevanayanam_.\n*   **Literary works:** Chillara Devullu, Modugupulu, Janapadam, Maya Jalataru, Saratalpam, Ranunnadi Edi Nizam, Sri Madramayanam, Sri Mahabharatam — with **Chillara Devullu** and **Modugupulu** the most prominent, describing the Telangana Struggles and the conditions before Telangana''s liberation.\n*   **Modugu Pulu** won the Kendra Sahitya Academy Award; **Chillera Devullu** won a National Literature Award and was adapted into a successful film directed by **T. Madhava Rao**.\n*   Translated all four Vedas into Telugu, and translated the Urdu classic _Umrao Jaan_ into Telugu.\n\n### Vattikota Alwar Swamy (1915–1961)\n\n*   Born in **Cheruvu Madaram** village, Nalgonda district; called **Telangana Vaithalika** (Pioneer) and **Telangana Gorki**.\n*   Raised by his teacher **Seetharama Rao** after his father''s early death.\n*   Jailed for participation in the **Quit India Movement (1942–43)**; came under communist influence and turned communist thereafter.\n*   Active in the library movement; fought against the Nizam and, for this, was imprisoned at **Induru Jail, Nizamabad, 1946–1951**, under rigorous punishment.\n*   **Literary works:** Jailu Lopala (life inside jail), Prajala Manishi (conditions of Telangana people, 1934–38), Gangu (Telangana people''s history, 1940–45), Telangana, Chinnappude, Ramappa Rabhasa (against social evils; published in _Telugu Vidyarthi_ patrika from Machilipatnam).\n*   Established **Deshoddaraka Grandhamala**, whose first published book was Suravaram Pratap Reddy''s _Prajadhikaramulu_.\n\n### Devulapalli Ramanuja Rao (1917–1993)\n\n*   Born in **Desai peta** village, Warangal district.\n*   Ran the newspaper _Shobha_ (literary monthly); served as President of the **Andhra Saraswatha Parishad** in 1953 (held at Alampur).\n*   **Literary works:** History of Telangana Armed Struggle, Telanganalo Jathiyodhyamalu, Saraswatha Navaneetham, Telugu Seemalo Samskrutika Punarjeevam, Hyderabad Swatantryodhyamam, Fifty Years of Remembrance (1929–79), Tenugu Literature, Veguchukkalu, Upanyasa Toranam, Kavya Mala, Talupula Dumaramu, Five Year Plans, My Radio Speeches, Our Village – Orugallu, Mana Desham – Telugu Seema.\n\n### Gadiyaram Ramakrishna Sharma\n\n*   Autobiography **Satapatram** (\"Hundred Petals\") won the **Kendra Sahitya Academy Award in 2007**, posthumously.\n*   **Literary works:** Madhava Vidyaranya Charitra, Alampura Kshethra Charitra, Veera Gadalu, Vignana Vallari, Dasharupaka Saram, Panchajanyam, Mana Vastu Sampada, Umamaheshwara Charitra.\n\n### Dr. C. Narayana Reddy (1931–2017)\n\n*   Born in **1931** at **Hanumajipet**, Karimnagar district.\n*   Won the prestigious **Jnanpith Award in 1988** for _Viswambhara_, becoming the **first person from Telangana** to receive it.\n*   Held a post-graduate degree and doctorate in Telugu literature from **Osmania University**, later becoming a professor there.\n*   **Awards:** 1973 – Kendra Sahitya Academy Award (for _Mantalu-Manavudu_); 1977 – Padma Shri; 1978 – Kala Prapoorna; 1988 – Jnanpith Award; 1992 – Padma Bhushan; 2014 – Kendra Sahitya Academy Fellowship.\n*   **Literary works:** Navvani Puvvu (1953, his first work), Ruthu Chakram, Vyakthithvam, Karpura Vasantha Rayalu, Bhugolamantha Manishi, Mattimanishi Aakasham, Mukhamukhi, Manishi–Chiluka, Ajanta Sundari, Vishwambhara, Kalam Sakshiga, Mantalu Manavudu, Nagarjuna Sagar, Bhoomika, Marpu Na Teerpu, Ramappa, Divvela Muvvalu.\n*   Entered the film industry as a lyricist with _Gulebhakavali Katha_ (1962), going on to write more than **3,000 songs**; became widely popular with the song \"Nannu Dochukunduvate Vannela Dorasani.\"\n\n### Other Literary Figures\n\n*   **Tadakamalla Krishna Rao (1830–1890)** wrote Telangana''s first novel, _Kambukandhara Charitra_.\n*   **Palla Durgaiah (1916–1983)** wrote Gangiredhu (Abull), Prabhanda Vajmaya Vikasam, and Palavelli. Together with Gangula Sai Reddy''s _Kapu Bidda_ and C. Narayana Reddy''s _Ruthu Chakram_, Palla Durgaiah''s _Gangireddu_ is treated as part of the modern-dialect **Kavyatrayam** (trio of poetic works).\n*   **Bunna Ilaiah** wrote the research work _Telangana Sahitya Samasthalu_, documenting the founding history of literary centres from Adilabad to Hyderabad, and depicted the lives of Telangana''s people in the story _Kaluva Mallaiah_. His other works include _Nippu Kanika_ and _Rahasya Chitram_.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter21-telangana-newspapers-literature';
